// bench1, form B+L: form B plus the float-literal path the generated bytecode
// actually takes.  bench1.class does, per literal per iteration,
//   FFloatLiteral.make(D)  then  CompilerBuiltin.coerce_RR64(FloatLiteral)
// and FFloatLiteral (runtimeValues/FFloatLiteral.java) stores the literal as a
// *String*: the constructor does new Double(val).toString(), and asRR64() does
// FRR64.make(Double.valueOf(val)).  So each literal is formatted to decimal and
// parsed back on every iteration.  This form reproduces that.
public class Bench1BoxedLit {

    static final class FRR64 {
        final double val;
        private FRR64(double x) { val = x; }
        public double getValue() { return val; }
        public static FRR64 make(double x) { return new FRR64(x); }
    }

    static final class FFloatLiteral {
        private String val;
        private FFloatLiteral(String val) { this.val = val; }
        private FFloatLiteral(double val) { this(Double.valueOf(val).toString()); }
        public static FFloatLiteral make(double x) { return new FFloatLiteral(x); }
        public FRR64 asRR64() { return FRR64.make(Double.valueOf(val)); }
    }

    static FRR64 coerce_RR64(FFloatLiteral l) { return l.asRR64(); }
    static FRR64 doubleMul(FRR64 a, FRR64 b) { return FRR64.make(a.getValue() * b.getValue()); }
    static FRR64 doubleAdd(FRR64 a, FRR64 b) { return FRR64.make(a.getValue() + b.getValue()); }

    public static void main(String[] args) {
        FRR64 acc = coerce_RR64(FFloatLiteral.make(0.0));
        long t0 = System.nanoTime();
        for (int i = 1; i <= 20000000; i++) {
            acc = doubleAdd(doubleMul(acc, coerce_RR64(FFloatLiteral.make(0.9999999))),
                            coerce_RR64(FFloatLiteral.make(0.0000001)));
        }
        long t1 = System.nanoTime();
        System.out.println("bench1 " + acc.getValue());
        System.out.println("loop_ns " + (t1 - t0));
    }
}
